AssertionFailed.example:
#include "cinux/assert.hpp"

using namespace cinux::base::safety;

void StopUnlessReady(bool ready) {
    if (!ready) {
        AssertionFailed("StopUnlessReady: caller must finish setup first");
        // 不返回 · 打印这句话和调用点，然后终止进程
    }
}

Check.example:
#include "cinux/assert.hpp"

using namespace cinux::base::safety;

void CheckExample() {
    Check(2 + 2 == 4, "arithmetic must hold");
    // 条件成立 → 直接返回，既不打印也不终止
}
